108	bool CheckTargetIndependentAsyncCopyPreconditions(const CopyNode &op) {
109	  if (!IsGlobalBuffer(op.src) || !IsSharedBuffer(op.dst)) {
110	    return false;
111	  }
112	  if (op.src->dtype != op.dst->dtype) {
113	    return false;
