118	bool CheckPipelineManagedCPAsyncCopy(const CopyNode &op,
119	                                     Optional<Target> target) {
120	  if (GetIsTmaCopy(op) || GetIsAsyncCopy(op) ||
121	      !CheckTargetIndependentAsyncCopyPreconditions(op)) {
122	    return false;
123	  }
124	  return !target.defined() || TargetHasAsyncCopy(target.value());
