140	Layout ExpandAnnotatedLayoutForMultiVersionedBuffer(const Layout &layout,
141	                                                    const Buffer &old_buffer,
142	                                                    const Buffer &new_buffer) {
143	  if (!layout.defined() ||
144	      new_buffer->shape.size() <= old_buffer->shape.size()) {
145	    return Layout();
146	  }
147	
148	  arith::Analyzer analyzer;
149	  if (!ShapesEqual(layout->InputShape(), old_buffer->shape, &analyzer)) {
150	    return Layout();
151	  }
152	
153	  size_t leading_ndim = new_buffer->shape.size() - old_buffer->shape.size();
154	  Array<PrimExpr> trailing_shape;
155	  Array<PrimExpr> leading_shape;
156	  for (size_t i = 0; i < leading_ndim; ++i) {
157	    leading_shape.push_back(new_buffer->shape[i]);
158	  }
159	  for (size_t i = 0; i < old_buffer->shape.size(); ++i) {
160	    trailing_shape.push_back(new_buffer->shape[leading_ndim + i]);
161	  }
162	  if (!ShapesEqual(trailing_shape, old_buffer->shape, &analyzer)) {
163	    return Layout();
164	  }
165	
166	  return layout->Expand(leading_shape);
167	}
