169	class BufferUsageCollector : public StmtExprVisitor {
170	public:
171	  BufferUsageCollector(const Map<Var, Buffer> &buffer_data_to_buffer,
172	                       const BufferSet &allocated_buffers)
173	      : buffer_data_to_buffer_(buffer_data_to_buffer),
174	        allocated_buffers_(allocated_buffers) {}
175	
176	  Array<Buffer> Collect(const Stmt &stmt) {
177	    this->VisitStmt(stmt);
178	    Array<Buffer> result;
179	    for (const auto &buffer : used_buffers_) {
180	      result.push_back(buffer);
181	    }
182	    return result;
183	  }
184	
185	private:
186	  void VisitStmt_(const BufferStoreNode *op) final {
187	    AddBuffer(op->buffer);
188	    StmtExprVisitor::VisitStmt_(op);
189	  }
190	
191	  void VisitExpr_(const BufferLoadNode *op) final {
192	    AddBuffer(op->buffer);
193	    StmtExprVisitor::VisitExpr_(op);
194	  }
195	
196	  void VisitExpr_(const CallNode *op) final {
197	    if (auto tile_op = ParseOperator(GetRef<Call>(op)); tile_op.defined()) {
198	      AccessRegions access = tile_op->GetAccessRegions();
199	      for (const auto &region : access.reads) {
200	        AddBuffer(region->buffer);
201	      }
202	      for (const auto &region : access.writes) {
203	        AddBuffer(region->buffer);
204	      }
205	      StmtExprVisitor::VisitExpr_(op);
206	      return;
207	    }
208	    // Handle tvm_access_ptr which also accesses buffers
209	    if (op->op.same_as(builtin::tvm_access_ptr())) {
210	      if (op->args.size() > 1) {
211	        if (const auto *var = op->args[1].as<VarNode>()) {
212	          auto it = buffer_data_to_buffer_.find(GetRef<Var>(var));
213	          if (it != buffer_data_to_buffer_.end()) {
214	            AddBuffer((*it).second);
215	          }
216	        }
217	      }
218	    }
219	    StmtExprVisitor::VisitExpr_(op);
220	  }
221	
222	  void VisitStmt_(const SBlockNode *op) final {
223	    // Also collect buffers allocated in nested blocks within the pipeline body
224	    for (const auto &buffer : op->alloc_buffers) {
225	      used_buffers_.insert(buffer);
226	    }
227	    StmtExprVisitor::VisitStmt_(op);
228	  }
229	
230	  void AddBuffer(const Buffer &buffer) {
231	    // Only add buffers that are allocated (not function input/output buffers)
232	    if (allocated_buffers_.count(buffer)) {
233	      used_buffers_.insert(buffer);
234	    }
235	  }
236	
237	  const Map<Var, Buffer> &buffer_data_to_buffer_;
238	  const BufferSet &allocated_buffers_;
239	  BufferSet used_buffers_;
240	};
