242	class TileOpAccessCollector : public StmtExprVisitor {
243	public:
244	  Array<BufferRegion> GetReads() const { return reads_; }
245	
246	  Array<BufferRegion> GetWrites() const { return writes_; }
247	
248	private:
249	  void VisitExpr_(const CallNode *op) final {
250	    if (auto tile_op = ParseOperator(GetRef<Call>(op)); tile_op.defined()) {
251	      AccessRegions access = tile_op->GetAccessRegions();
252	      reads_.insert(reads_.end(), access.reads.begin(), access.reads.end());
253	      writes_.insert(writes_.end(), access.writes.begin(), access.writes.end());
254	      StmtExprVisitor::VisitExpr_(op);
255	      return;
256	    }
257	    StmtExprVisitor::VisitExpr_(op);
258	  }
259	
260	  Array<BufferRegion> reads_;
261	  Array<BufferRegion> writes_;
262	};
