264	class SimtProducerAnnotator : public StmtExprMutator {
265	public:
266	  static Stmt Annotate(const Stmt &stmt,
267	                       Optional<Target> target = Optional<Target>()) {
268	    SimtProducerAnnotator annotator(std::move(target));
269	    return annotator.VisitStmt(stmt);
270	  }
271	
272	private:
273	  explicit SimtProducerAnnotator(Optional<Target> target)
274	      : target_(std::move(target)) {}
275	
276	  Stmt VisitStmt_(const ForNode *op) final {
277	    Stmt body = VisitStmt(op->body);
278	    auto annotations = op->annotations;
279	    // Keep SIMT copy lowering under the outer pipeline-managed commit/wait
280	    // semantics as well.
281	    annotations.Set(attr::kParallelAsyncWithoutAsyncCommitWait, Bool(true));
282	    return For(op->loop_var, op->min, op->extent, op->kind, body,
283	               op->thread_binding, annotations, op->step, op->span);
284	  }
285	
286	  PrimExpr VisitExpr_(const CallNode *op) final {
287	    static const Op &copy_op = Op::Get("tl.tileop.copy");
288	    Call call = Downcast<Call>(StmtExprMutator::VisitExpr_(op));
289	    if (!call->op.same_as(copy_op) || !CanUsePipelineManagedCPAsyncCopy(call)) {
290	      return call;
291	    }
292	    // Tile-op copies lower through copy.cc, so they need an explicit
293	    // per-copy marker to suppress their own implicit commit/wait.
294	    auto annotations = call->annotations;
295	    annotations.Set(attr::kAsyncCopyNoImplicitCommitWait,
296	                    IntImm(DataType::Int(32), 1));
297	    return Call(call->dtype, call->op, call->args, annotations, call->span);
298	  }
299	
300	  bool CanUsePipelineManagedCPAsyncCopy(const Call &call) const {
301	    auto tile_op = ParseOperator(call);
302	    const auto *copy = tile_op.as<CopyNode>();
303	    if (copy == nullptr) {
304	      return false;
305	    }
306	    return CheckPipelineManagedCPAsyncCopy(*copy, target_);
307	  }
308	
309	  Optional<Target> target_;
310	};
