323	  PrimExpr VisitExpr_(const CallNode *op) final {
324	    Call call = Downcast<Call>(StmtExprMutator::VisitExpr_(op));
325	    if (!IsMbarPhaseConsumer(call)) {
326	      return call;
327	    }
328	    if (call->annotations.count(attr::kPipelineMbarPhaseExpr)) {
329	      return call;
330	    }
331	    auto annotations = call->annotations;
332	    annotations.Set(attr::kPipelineMbarPhaseExpr, phase_expr_);
333	    return Call(call->dtype, call->op, call->args, annotations, call->span);
334	  }
