336	  bool IsMbarPhaseConsumer(const Call &call) const {
337	    auto tile_op = ParseOperator(call);
338	    return tile_op.defined() && (tile_op.as<CopyNode>() != nullptr ||
339	                                 tile_op.as<Im2ColOpNode>() != nullptr ||
340	                                 tile_op.as<GemmNode>() != nullptr);
341	  }
