405	bool UpdateExpandedLayoutMapForRemappedAllocs(
406	    const std::vector<std::pair<Buffer, Buffer>> &remapped_allocs,
407	    Map<String, Any> *annotations) {
408	  if (remapped_allocs.empty() || !annotations->count(attr::kLayoutMap)) {
409	    return false;
410	  }
411	
412	  auto layout_map_ref = annotations->Get(attr::kLayoutMap);
413	  if (!layout_map_ref.has_value()) {
414	    return false;
415	  }
416	  auto layout_map = layout_map_ref.value().as<Map<Var, Layout>>();
417	  if (!layout_map.has_value()) {
418	    return false;
419	  }
420	
421	  Map<Var, Layout> updated_layout_map = layout_map.value();
422	  VarSet visited;
423	  bool changed = false;
424	  for (const auto &[old_buffer, new_buffer] : remapped_allocs) {
425	    if (!visited.insert(old_buffer->data).second ||
426	        !updated_layout_map.count(old_buffer->data)) {
427	      continue;
428	    }
429	    Layout layout = updated_layout_map[old_buffer->data];
430	    Layout expanded = ExpandAnnotatedLayoutForMultiVersionedBuffer(
431	        layout, old_buffer, new_buffer);
432	    if (!expanded.defined()) {
433	      continue;
434	    }
435	    updated_layout_map.Set(old_buffer->data, expanded);
436	    changed = true;
437	  }
438	
439	  if (changed) {
440	    annotations->Set(attr::kLayoutMap, updated_layout_map);
441	  }
442	  return changed;
443	}
