453	/*!
454	 * \brief Create a block and infer the access region with the given body.
455	 *
456	 * The result is a opaque block that doesn't contain any block iter vars. In
457	 * case the body is a block realize without predicate, it is unnecessary to
458	 * create a new block, the block of the block realize will be returned.
459	 *
460	 * \param body The body of the block.
461	 * \param buffer_data_to_buffer The map from buffer data to buffer.
462	 * \return The result block.
463	 */
464	SBlock MakeBlock(const Stmt &body,
465	                 const Map<Var, Buffer> &buffer_data_to_buffer) {
466	  SBlock block;
467	  if (const SBlockRealizeNode *block_realize = body.as<SBlockRealizeNode>()) {
468	    if (is_one(block_realize->predicate)) {
469	      block = block_realize->block;
470	    }
471	  }
472	  if (!block.defined()) {
473	    block = SBlock(/*iter_vars=*/{}, /*reads=*/{}, /*writes=*/{},
474	                   /*name_hint=*/"", /*body*/ body);
475	  }
476	  Array<Array<BufferRegion>> access =
477	      GetSBlockReadWriteRegion(block, buffer_data_to_buffer);
478	  TileOpAccessCollector collector;
479	  collector(block->body);
480	  Array<BufferRegion> tile_reads = collector.GetReads();
481	  Array<BufferRegion> tile_writes = collector.GetWrites();
482	  SBlockNode *n = block.CopyOnWrite();
483	  n->reads = access[0];
484	  n->reads.insert(n->reads.end(), tile_reads.begin(), tile_reads.end());
485	  n->writes = access[1];
486	  n->writes.insert(n->writes.end(), tile_writes.begin(), tile_writes.end());
487	  return block;
488	}
