495	    }
496	    if (const auto *attr = obj.as<AttrStmtNode>()) {
497	      if (attr->attr_key == s_tir::attr::async_commit_queue_scope ||
498	          attr->attr_key == s_tir::attr::async_wait_queue_scope ||
499	          attr->attr_key == s_tir::attr::async_wait_inflight_count) {
500	        found = true;
501	        return;
502	      }
503	    }
504	  });
505	  return found;
506	}
