557	/*!
558	 * \brief Rewrite a block's body, converting tl.tileop.copy calls to
559	 *        tl.tileop.tma_copy with barrier and emit_arrive annotations.
560	 */
561	class CopyToTmaCopyRewriter : public StmtExprMutator {
562	public:
563	  CopyToTmaCopyRewriter(const Buffer &barrier_buf, PrimExpr barrier_id,
564	                        bool emit_arrive = true)
565	      : barrier_buf_(barrier_buf), barrier_id_(std::move(barrier_id)),
566	        emit_arrive_(emit_arrive) {}
567	
568	  PrimExpr VisitExpr_(const CallNode *op) final {
569	    static const Op &copy_op = Op::Get("tl.tileop.copy");
570	    static const Op &tma_copy_op = Op::Get("tl.tileop.tma_copy");
571	    static const Op &im2col_op = Op::Get("tl.tileop.im2col");
572	    static const Op &deprecated_c2d_im2col_op = Op::Get("tl.tileop.c2d_im2col");
573	    Call call = Downcast<Call>(StmtExprMutator::VisitExpr_(op));
574	    if (call->op.same_as(copy_op)) {
575	      auto new_annotations = call->annotations;
576	      new_annotations.Set("barrier", MakeBarrierRef(barrier_buf_, barrier_id_));
577	      new_annotations.Set("is_tma_copy", IntImm(DataType::Int(32), 1));
578	      new_annotations.Set("emit_arrive",
579	                          IntImm(DataType::Int(32), emit_arrive_ ? 1 : 0));
580	      return Call(call->dtype, tma_copy_op, call->args, new_annotations,
581	                  call->span);
582	    }
583	    // Annotate im2col with pipeline barrier so its Lower() uses it
584	    // instead of allocating a separate internal barrier.
585	    if (call->op.same_as(im2col_op) ||
586	        call->op.same_as(deprecated_c2d_im2col_op)) {
587	      auto new_annotations = call->annotations;
588	      new_annotations.Set("barrier", MakeBarrierRef(barrier_buf_, barrier_id_));
589	      new_annotations.Set("emit_arrive",
590	                          IntImm(DataType::Int(32), emit_arrive_ ? 1 : 0));
591	      return Call(call->dtype, call->op, call->args, new_annotations,
592	                  call->span);
593	    }
594	    return call;
595	  }
596	
597	private:
598	  Buffer barrier_buf_;
599	  PrimExpr barrier_id_;
600	  bool emit_arrive_;
601	};
