607	/// Collect all shared.barrier Buffer objects referenced in a statement.
608	class BarrierBufferCollector : public StmtExprVisitor {
609	public:
610	  static std::vector<Buffer> Collect(const Array<SBlock> &blocks) {
611	    BarrierBufferCollector c;
612	    for (const auto &block : blocks) {
613	      c(block->body);
614	    }
615	    return {c.barriers_.begin(), c.barriers_.end()};
616	  }
617	
618	private:
619	  void VisitExpr_(const BufferLoadNode *op) final {
620	    if (op->buffer.scope() == "shared.barrier" ||
621	        op->buffer.scope() == "shared.cluster_barrier") {
622	      if (!seen_.count(op->buffer)) {
623	        seen_.insert(op->buffer);
624	        barriers_.push_back(op->buffer);
625	      }
626	    }
627	    StmtExprVisitor::VisitExpr_(op);
628	  }
629	
630	  void VisitStmt_(const BufferStoreNode *op) final {
631	    if (op->buffer.scope() == "shared.barrier" ||
632	        op->buffer.scope() == "shared.cluster_barrier") {
633	      if (!seen_.count(op->buffer)) {
634	        seen_.insert(op->buffer);
635	        barriers_.push_back(op->buffer);
636	      }
637	    }
638	    StmtExprVisitor::VisitStmt_(op);
639	  }
640	
641	  // Also check barrier refs inside Call annotations (e.g., tma_copy barrier).
642	  void VisitExpr_(const CallNode *op) final {
643	    for (const auto &[key, val] : op->annotations) {
644	      if (auto load = val.as<BufferLoadNode>()) {
645	        if (load->buffer.scope() == "shared.barrier" ||
646	            load->buffer.scope() == "shared.cluster_barrier") {
647	          if (!seen_.count(load->buffer)) {
648	            seen_.insert(load->buffer);
649	            barriers_.push_back(load->buffer);
650	          }
651	        }
652	      }
653	    }
654	    StmtExprVisitor::VisitExpr_(op);
655	  }
656	
657	  BufferSet seen_;
658	  std::vector<Buffer> barriers_;
659	};
