886	/*!
887	 * \brief Rewrite TMA-eligible copy blocks in the pipeline body for
888	 *        pipeline-level barrier management.
889	 *
890	 * For each TMA copy: convert tl.tileop.copy to tl.tileop.tma_copy with a
891	 * per-stage barrier slot and emit_arrive=1 so LowerTileOp emits arrive inside
892	 * the thread-0 guard.
893	 *
894	 * For the first consumer stage block: prepend mbarrier_wait_parity with
895	 * stage-indexed barrier reference and parity expression.
896	 *
897	 * \param original_order  In/out: blocks in original pipeline order.
898	 * \param pipeline_info   In/out: block to PipelineAnnotation mapping.
899	 * \param tma_copies      Per-statement TMA flag array from PipelinePlanning.
900	 * \param buffer_data_to_buffer  In/out: buffer var to Buffer mapping.
901	 * \param allocated_buffers      In/out: set of allocated buffers.
902	 * \param block_local_allocs     In/out: buffers allocated in the pipeline
903	 * block.
904	 * \return The newly created barrier buffer (undefined if no TMA copies).
905	 */
906	Buffer RewritePipelineTmaBarriers(
907	    Array<SBlock> &original_order, PipelineInfo &pipeline_info,
908	    const Array<Integer> &tma_copies, Map<Var, Buffer> &buffer_data_to_buffer,
909	    BufferSet &allocated_buffers, Array<Buffer> &block_local_allocs,
910	    Var loop_var, PrimExpr loop_min, int num_stages) {
911	  if (!std::any_of(tma_copies.begin(), tma_copies.end(),
912	                   [](const Integer &tc) { return !is_zero(tc); })) {
913	    return Buffer();
914	  }
915	
916	  // Create pipeline barrier buffer with a single slot.  The generic
917	  // ExpandPipelineBarriers pass (called later) will expand it to
918	  // num_stages slots along with all other barrier buffers.
919	  Buffer barrier_buf = CreateMBarrierBuffer("pipeline_mbar", 1);
920	  buffer_data_to_buffer.Set(barrier_buf->data, barrier_buf);
921	  allocated_buffers.insert(barrier_buf);
922	  block_local_allocs.push_back(barrier_buf);
923	
924	  // Find the index of the last TMA copy for arrive emission.
925	  int last_tma_idx = -1;
926	  for (size_t i = 0; i < original_order.size(); i++) {
927	    if (!is_zero(tma_copies[i]))
928	      last_tma_idx = static_cast<int>(i);
929	  }
930	
931	  // Phase 1: Rewrite TMA copy blocks - all share barrier slot 0.
932	  // ExpandPipelineBarriers (called later) will rewrite indices to be
933	  // stage-dependent.  Only the last TMA copy emits arrive.
934	  for (size_t i = 0; i < original_order.size(); i++) {
935	    if (is_zero(tma_copies[i]))
936	      continue;
937	
938	    bool is_last = (static_cast<int>(i) == last_tma_idx);
939	    SBlock old_block = original_order[i];
940	    CopyToTmaCopyRewriter rewriter(barrier_buf,
941	                                   /*barrier_id=*/IntImm(DataType::Int(32), 0),
942	                                   /*emit_arrive=*/is_last);
943	    Stmt new_body = rewriter(old_block->body);
944	
945	    SBlock new_block(old_block->iter_vars, old_block->reads, old_block->writes,
946	                     old_block->name_hint, new_body, old_block->init,
947	                     old_block->alloc_buffers, old_block->match_buffers,
948	                     old_block->annotations);
949	
950	    PipelineAnnotation anno = pipeline_info.at(old_block);
951	    pipeline_info.erase(old_block);
952	    pipeline_info.emplace(new_block, anno);
953	    original_order.Set(i, new_block);
954	  }
955	
956	  // Phase 2: Insert waits in consumer blocks (blocks that depend on TMA data).
957	  // For simplicity, we insert waits before the first block whose stage > 0.
958	  bool waits_inserted = false;
959	  for (size_t i = 0; i < original_order.size(); i++) {
960	    if (waits_inserted)
961	      break;
962	    SBlock old_block = original_order[i];
963	    int stage = pipeline_info.at(old_block).stage;
964	    if (stage == 0)
965	      continue; // still in producer stage
966	
967	    // Wait on barrier slot 0 with single-slot parity.
968	    // ExpandPipelineBarriers will rewrite index and parity for versioning.
969	    Array<Stmt> wait_stmts;
970	    {
971	      PrimExpr barrier_ref =
972	          MakeBarrierRef(barrier_buf, IntImm(DataType::Int(32), 0));
973	      PrimExpr ns = IntImm(DataType::Int(32), num_stages);
974	      PrimExpr parity = FloorMod(FloorDiv(loop_var - loop_min, ns), 2);
975	      wait_stmts.push_back(Evaluate(Call(
976	          DataType::Handle(), mbarrier_wait_parity(), {barrier_ref, parity})));
977	    }
978	    wait_stmts.push_back(old_block->body);
979	    Stmt new_body = SeqStmt(wait_stmts);
980	
981	    SBlock new_block(old_block->iter_vars, old_block->reads, old_block->writes,
982	                     old_block->name_hint, new_body, old_block->init,
983	                     old_block->alloc_buffers, old_block->match_buffers,
984	                     old_block->annotations);
985	
986	    PipelineAnnotation anno = pipeline_info.at(old_block);
987	    pipeline_info.erase(old_block);
988	    pipeline_info.emplace(new_block, anno);
989	    original_order.Set(i, new_block);
990	    waits_inserted = true;
991	  }
992	
993	  return barrier_buf;
994	}
