1159	/*!
1160	 * \brief Rewriter for the software pipeline that rewrite a loop into a
1161	 * pipelined one.
1162	 */
1163	class PipelineRewriter : public StmtExprMutator {
1164	public:
1165	  /*!
1166	   * \brief Constructor of PipelineRewriter.
1167	   * \param buffer_data_to_buffer The map from buffer data to buffer.
1168	   * \param pipeline_allocs All buffers that need multi-versioning in the
1169	   * pipeline. This includes buffers allocated in the pipeline block and
1170	   * buffers allocated in outer blocks that are used in the pipeline.
1171	   * \param local_allocs Buffers that are allocated in the pipeline block
1172	   * itself. These buffers will be re-allocated in the rewritten block.
1173	   * Buffers in pipeline_allocs but not in local_allocs are allocated in outer
1174	   * blocks and should not be re-allocated.
1175	   * \param pipeline_loop The original loop to be software pipelined.
1176	   * \param pipeline_info The pipeline annotation information.
1177	   * \param scalar_binding_blocks Replayable scalar Bind statements from the
1178	   * pipeline body.
1179	   */
1180	  PipelineRewriter(Map<Var, Buffer> buffer_data_to_buffer,
1181	                   const Array<Buffer> &pipeline_allocs,
1182	                   const Array<Buffer> &local_allocs, const For &pipeline_loop,
1183	                   const PipelineInfo &pipeline_info,
1184	                   const Array<SBlock> &scalar_binding_blocks,
1185	                   Optional<Target> target)
1186	      : buffer_data_to_buffer_(std::move(buffer_data_to_buffer)),
1187	        pipeline_allocs_(pipeline_allocs), local_allocs_(local_allocs),
1188	        pipeline_loop_(pipeline_loop), pipeline_info_(pipeline_info),
1189	        scalar_binding_blocks_(scalar_binding_blocks),
1190	        target_(std::move(target)) {}
1191	
1192	  Stmt BuildPipeline() {
1193	    // Step 1: Analyze accesses to the buffers in the pipeline and compute the
1194	    // number of versions need to maintain for each buffer.
1195	    std::unordered_map<Buffer, BufferAccessInfo, ObjectPtrHash, ObjectPtrEqual>
1196	        infos = GetBufferAccessInfo();
1197	    for (const Buffer &buffer : pipeline_allocs_) {
1198	      auto it = infos.find(buffer);
1199	      if (it == infos.end()) {
1200	        // Buffer is not accessed in the pipeline blocks, skip it
1201	        continue;
1202	      }
1203	      int num_versions = ComputeBufferVersions(buffer, it->second);
1204	      if (num_versions > 1) {
1205	        buffer_remap_.Set(buffer, RewriteAllocBuffer(buffer, num_versions));
1206	      }
1207	    }
1208	    std::vector<std::pair<int, SBlock>> ordered_blocks;
1209	    for (const auto &[block, anno] : pipeline_info_) {
1210	      ordered_blocks.emplace_back(anno.order, block);
1211	    }
1212	    std::sort(
1213	        ordered_blocks.begin(), ordered_blocks.end(),
1214	        [](const auto &lhs, const auto &rhs) { return lhs.first < rhs.first; });
1215	    for (const auto &[_, block] : ordered_blocks) {
1216	      ordered_stmts_.push_back(block);
1217	    }
1218	    CollectScalarBindings();
1219	
1220	    // Step 2: Emit the pipeline prologue, body and epilogue.
1221	    Optional<Integer> pipeline_num_stages =
1222	        GetPipelineNumStages(pipeline_loop_.get());
1223	    Stmt prologue = EmitImpl(pipeline_loop_->min,
1224	                             pipeline_loop_->min + max_stage_, true, true);
1225	    Stmt body =
1226	        EmitImpl(pipeline_loop_->min + max_stage_,
1227	                 pipeline_loop_->min + pipeline_loop_->extent, false, false);
1228	    Stmt epilogue = EmitImpl(
1229	        pipeline_loop_->min + pipeline_loop_->extent,
1230	        pipeline_loop_->min + pipeline_loop_->extent + max_stage_, true, true);
1231	
1232	    Array<Stmt> pipeline_parts;
1233	    for (const Stmt &part : {prologue, body, epilogue}) {
1234	      for (const Stmt &stmt : FlattenTopLevelSeq(part)) {
1235	        pipeline_parts.push_back(stmt);
1236	      }
1237	    }
1238	
1239	    Stmt stmt = pipeline_parts.size() == 1 ? pipeline_parts[0]
1240	                                           : SeqStmt(pipeline_parts);
1241	    stmt = AsyncPipelineLoopWaitRelaxer(this)(stmt);
1242	    Array<Stmt> relaxed_pipeline_parts = FlattenTopLevelSeq(stmt);
1243	    relaxed_pipeline_parts =
1244	        RelaxTrailingConsumerWaits(std::move(relaxed_pipeline_parts),
1245	                                   PipelinedRetainGroups(pipeline_num_stages));
1246	    stmt = relaxed_pipeline_parts.size() == 1 ? relaxed_pipeline_parts[0]
1247	                                              : SeqStmt(relaxed_pipeline_parts);
1248	
1249	    // Step 3: Make a new block only when the rewritten pipeline owns local
1250	    // allocations.  When all buffers are already allocated by an outer block
1251	    // (the common TileLang kernel-root case), an extra synthetic scope would
1252	    // only carry a very large inferred read/write region and make the IR hard
1253	    // to inspect.
1254	    if (local_allocs_.empty()) {
1255	      return stmt;
1256	    }
1257	
1258	    // Only include buffers that are locally allocated in the pipeline block.
1259	    // Buffers from outer blocks will be handled separately.
1260	    Array<Buffer> alloc_buffers;
1261	    for (const auto &alloc : local_allocs_) {
1262	      alloc_buffers.push_back(buffer_remap_.Get(alloc).value_or(alloc));
1263	      buffer_data_to_buffer_.erase(alloc->data);
1264	    }
1265	    SBlock block = MakeBlock(stmt, buffer_data_to_buffer_);
1266	    block.CopyOnWrite()->alloc_buffers = std::move(alloc_buffers);
1267	    return SBlockRealize({}, Bool(true), block);
1268	  }
1269	
1270	  /*!
1271	   * \brief Get the buffer remapping created during pipeline rewriting.
1272	   * This is used to update alloc_buffers in outer blocks.
1273	   */
1274	  const Map<Buffer, Buffer> &GetBufferRemap() const { return buffer_remap_; }
