1286	  void CollectScalarBindings() {
1287	    scalar_bindings_.clear();
1288	    scalar_binding_map_.clear();
1289	    for (const SBlock &block : scalar_binding_blocks_) {
1290	      if (const auto *bind = block->body.as<BindNode>()) {
1291	        if (!scalar_binding_map_.count(bind->var)) {
1292	          scalar_binding_map_.emplace(bind->var, scalar_bindings_.size());
1293	          scalar_bindings_.push_back({bind->var, bind->value, bind->span});
1294	        }
1295	      }
1296	    }
1297	  }
