1299	  VarSet FindScalarBindingUses(const Array<Var> &undefined_vars) const {
1300	    VarSet uses;
1301	    for (const Var &var : undefined_vars) {
1302	      if (scalar_binding_map_.count(var)) {
1303	        uses.insert(var);
1304	      }
1305	    }
1306	    return uses;
1307	  }
1308	
1309	  VarSet FindScalarBindingUses(const Stmt &stmt) const {
1310	    return FindScalarBindingUses(UndefinedVars(stmt, Array<Var>{}));
1311	  }
1312	
1313	  VarSet FindScalarBindingUses(const PrimExpr &expr) const {
1314	    return FindScalarBindingUses(UndefinedVars(expr));
1315	  }
1316	
1317	  void AppendScalarBinding(size_t binding_index, VarSet *emitted,
1318	                           VarSet *visiting,
1319	                           std::vector<size_t> *binding_indices) const {
1320	    const ScalarBinding &binding = scalar_bindings_[binding_index];
1321	    if (emitted->count(binding.var)) {
1322	      return;
1323	    }
1324	    ICHECK(!visiting->count(binding.var))
1325	        << "InjectSoftwarePipeline: cyclic scalar Bind dependency involving "
1326	        << binding.var;
1327	
1328	    visiting->insert(binding.var);
1329	    VarSet deps = FindScalarBindingUses(binding.value);
1330	    for (const ScalarBinding &candidate : scalar_bindings_) {
1331	      if (!deps.count(candidate.var)) {
1332	        continue;
1333	      }
1334	      auto it = scalar_binding_map_.find(candidate.var);
1335	      ICHECK(it != scalar_binding_map_.end());
1336	      AppendScalarBinding(it->second, emitted, visiting, binding_indices);
1337	    }
1338	    visiting->erase(binding.var);
1339	
1340	    emitted->insert(binding.var);
1341	    binding_indices->push_back(binding_index);
1342	  }
1343	
1344	  std::vector<size_t> RequiredScalarBindings(const Stmt &stmt) const {
1345	    std::vector<size_t> binding_indices;
1346	    if (scalar_bindings_.empty()) {
1347	      return binding_indices;
1348	    }
1349	
1350	    VarSet uses = FindScalarBindingUses(stmt);
1351	    if (uses.empty()) {
1352	      return binding_indices;
1353	    }
1354	
1355	    VarSet emitted;
1356	    VarSet visiting;
1357	    for (const ScalarBinding &binding : scalar_bindings_) {
1358	      if (!uses.count(binding.var)) {
1359	        continue;
1360	      }
1361	      auto it = scalar_binding_map_.find(binding.var);
1362	      ICHECK(it != scalar_binding_map_.end());
1363	      AppendScalarBinding(it->second, &emitted, &visiting, &binding_indices);
1364	    }
1365	    return binding_indices;
1366	  }
1367	
1368	  Stmt RewriteScalarBindingForAccess(size_t binding_index,
1369	                                     const PrimExpr &access_index) {
1370	    const ScalarBinding &binding = scalar_bindings_[binding_index];
1371	    Stmt bind = Bind(binding.var, binding.value, binding.span);
1372	    bind = PipelineBodyRewriter(buffer_data_to_buffer_, buffer_remap_,
1373	                                pipeline_loop_, max_stage_ != 1)(bind);
1374	    bind = Substitute(bind, {{pipeline_loop_->loop_var, access_index}});
1375	    return bind;
1376	  }
1377	
1378	  SBlock ReplayScalarBindings(SBlock block, const PrimExpr &access_index) {
1379	    std::vector<size_t> binding_indices = RequiredScalarBindings(block->body);
1380	    if (binding_indices.empty()) {
1381	      return block;
1382	    }
1383	
1384	    Array<Stmt> seq;
1385	    for (size_t binding_index : binding_indices) {
1386	      seq.push_back(RewriteScalarBindingForAccess(binding_index, access_index));
1387	    }
1388	    for (const Stmt &stmt : FlattenTopLevelSeq(block->body)) {
1389	      seq.push_back(stmt);
1390	    }
1391	
1392	    SBlockNode *n = block.CopyOnWrite();
1393	    n->body = SeqStmt(seq);
1394	    return MakeBlock(SBlockRealize({}, Bool(true), block),
1395	                     buffer_data_to_buffer_);
1396	  }
1397	
1398	  /*!
1399	   * \brief Analyze accesses to the buffers in the software pipeline.
1400	   *
1401	   * This method check the 'define' and 'use' stage of the buffers in the
1402	   * software pipeline, which can be used to compute the number of versions
1403	   * needed to maintain after rewriting.
1404	   */
1405	  std::unordered_map<Buffer, BufferAccessInfo, ObjectPtrHash, ObjectPtrEqual>
1406	  GetBufferAccessInfo() {
1407	    std::unordered_map<Buffer, BufferAccessInfo, ObjectPtrHash, ObjectPtrEqual>
1408	        infos;
1409	    for (const auto &pair : pipeline_info_) {
1410	      const SBlock &block = pair.first;
1411	      int stage = pair.second.stage;
1412	      max_stage_ = std::max(max_stage_, stage);
1413	
1414	      for (const BufferRegion &write : block->writes) {
1415	        if (!infos.count(write->buffer)) {
1416	          infos.emplace(write->buffer, BufferAccessInfo{});
1417	        }
1418	        auto &info = infos.at(write->buffer);
1419	        if (info.def == -1) {
1420	          info.def = stage;
1421	        } else {
1422	          info.def = std::min(info.def, stage);
1423	        }
1424	      }
1425	
1426	      for (const BufferRegion &read : block->reads) {
1427	        if (!infos.count(read->buffer)) {
1428	          infos.emplace(read->buffer, BufferAccessInfo{});
1429	        }
1430	        auto &info = infos.at(read->buffer);
1431	        info.use = std::max(info.use, stage);
1432	      }
1433	    }
1434	    return infos;
1435	  }
1436	
1437	  /*!
1438	   * \brief Check whether two regions have intersections.
1439	   * \param region1 The first region.
1440	   * \param region2 The second region.
1441	   * \return Whether region1 and region2 have intersections.
1442	   */
1443	  bool MayConflict(const Region &region1, const Region &region2) {
1444	    ICHECK(region1.size() == region2.size());
1445	    for (size_t i = 0; i < region1.size(); i++) {
1446	      Range dim1 = region1[i];
1447	      Range dim2 = region2[i];
1448	      auto int_set1 = arith::IntSet::FromRange(dim1);
1449	      auto int_set2 = arith::IntSet::FromRange(dim2);
1450	      if (arith::Intersect({int_set1, int_set2}).IsNothing()) {
1451	        return false;
1452	      }
1453	    }
1454	    return true;
1455	  }
1456	
1457	  /*!
1458	   * \brief Compute the number of versions need to maintain for buffer accessed
1459	   * in the software pipeline.
1460	   *
1461	   * This method applies liveness analysis to the target buffer to compute the
1462	   * number of versions need to maintain during the software pipeline.
1463	   * Annotation `attr::double_buffer_scope` is handled here which provides a way
1464	   * to override the result of the analysis. Additional double buffering in the
1465	   * software pipeline can be useful to eliminate synchronizations in GPU
1466	   * devices.
1467	   *
1468	   * \param buffer The target buffer
1469	   * \param buffer_info The access information of the target buffer.
1470	   * \return The number of versions required for the target buffer.
1471	   */
1472	  int ComputeBufferVersions(const Buffer &buffer,
1473	                            const BufferAccessInfo &buffer_info) {
1474	    if (buffer_info.def == -1) {
1475	      // Keep the original number of versions as buffers defined outside the
1476	      // software pipeline should not be mutated.
1477	      return 1;
1478	    }
1479	
1480	    // `use - def + 1` is a upper bound of the needed versions
1481	    // We optimize a few case where the number of versions can be smaller than
1482	    // the upper bound
1483	    int num_versions = buffer_info.use - buffer_info.def + 1;
1484	    if (num_versions >= 2) {
1485	      // A special case when `use - def + 1 == 2`. Double buffering is only
1486	      // needed in this case when these exists a reader block_i and a writer
1487	      // block_j such that order(block_i) < order(block_j) and stage(block_i) <
1488	      // stage(block_j) and the access regions of block_i and block_j overlap.
1489	      bool need_multi_version = false;
1490	      for (const auto &pair1 : pipeline_info_) {
1491	        const SBlock &writer_block = pair1.first;
1492	        const auto &writer_info = pair1.second;
1493	
1494	        auto it1 = std::find_if(writer_block->writes.begin(),
1495	                                writer_block->writes.end(),
1496	                                [&](const BufferRegion &buffer_region) {
1497	                                  return buffer_region->buffer.same_as(buffer);
1498	                                });
1499	        if (it1 == writer_block->writes.end()) {
1500	          continue;
1501	        }
1502	
1503	        for (const auto &pair2 : pipeline_info_) {
1504	          const SBlock &reader_block = pair2.first;
1505	          const auto &reader_info = pair2.second;
1506	          auto it2 = std::find_if(
1507	              reader_block->reads.begin(), reader_block->reads.end(),
1508	              [&](const BufferRegion &buffer_region) {
1509	                return buffer_region->buffer.same_as(buffer);
1510	              });
1511	          if (it2 == reader_block->reads.end()) {
1512	            continue;
1513	          }
1514	          if (writer_info.order < reader_info.order &&
1515	              writer_info.stage < reader_info.stage &&
1516	              MayConflict((*it1)->region, (*it2)->region)) {
1517	            need_multi_version = true;
1518	            break;
1519	          }
1520	        }
1521	      }
1522	      if (!need_multi_version) {
1523	        num_versions--;
1524	      }
1525	    }
1526	    return num_versions;
1527	  }
1528	
1529	  /*!
1530	   * \brief Rewrite buffer allocation to keep multiple versions of original
1531	   * buffer for pipelined accesses. \param buffer The buffer to be resized.
1532	   * \param num_versions The number of versions to keep.
1533	   * \return The resized buffer.
1534	   */
1535	  Buffer RewriteAllocBuffer(const Buffer &buffer, int num_versions) {
1536	    ObjectPtr<BufferNode> new_buffer = make_object<BufferNode>(*(buffer.get()));
1537	    new_buffer->shape.insert(new_buffer->shape.begin(), PrimExpr(num_versions));
1538	    if (!new_buffer->strides.empty()) {
1539	      ICHECK(new_buffer->strides.size() + 1 == new_buffer->shape.size());
1540	      PrimExpr stride_0 = new_buffer->strides[0] * new_buffer->shape[1];
1541	      new_buffer->strides.insert(new_buffer->strides.begin(), stride_0);
1542	    }
1543	    return Buffer(new_buffer);
1544	  }
