1644	
1645	  // Analyze a stmt for one specific question used by wait relaxation:
1646	  // can we prove that it contributes a deterministic number of commit groups
1647	  // without crossing a wait boundary? The analyzer exposes the effect as
1648	  // structured state instead of overloading std::optional<int> with both
1649	  // "unknown" and "has wait" meanings.
1650	  class DeterministicNoWaitCommitAnalyzer {
1651	  public:
1652	    explicit DeterministicNoWaitCommitAnalyzer(const PipelineRewriter *rewriter)
1653	        : rewriter_(rewriter) {}
1654	
1655	    DeterministicNoWaitCommitEffect Analyze(const Stmt &stmt) const {
1656	      if (stmt.as<BindNode>()) {
1657	        return DeterministicNoWaitCommitEffect{};
1658	      }
1659	      if (const auto *attr = stmt.as<AttrStmtNode>()) {
1660	        return AnalyzeAttr(attr);
1661	      }
1662	      if (const auto *seq = stmt.as<SeqStmtNode>()) {
1663	        DeterministicNoWaitCommitEffect effect;
1664	        for (const Stmt &s : seq->seq) {
1665	          effect = Combine(effect, Analyze(s));
1666	          if (!effect.deterministic) {
1667	            return effect;
1668	          }
1669	        }
1670	        return effect;
1671	      }
1672	      if (const auto *block = stmt.as<SBlockNode>()) {
1673	        return Analyze(block->body);
1674	      }
1675	      if (const auto *realize = stmt.as<SBlockRealizeNode>()) {
1676	        if (!is_one(realize->predicate)) {
1677	          return DeterministicNoWaitCommitEffect::Unknown();
1678	        }
1679	        return Analyze(realize->block->body);
1680	      }
1681	      if (const auto *for_node = stmt.as<ForNode>()) {
1682	        return AnalyzeFor(for_node);
1683	      }
1684	      if (stmt.as<IfThenElseNode>()) {
1685	        return DeterministicNoWaitCommitEffect::Unknown();
1686	      }
1687	      if (rewriter_->ContainsAsyncSyncScopes(stmt)) {
1688	        return DeterministicNoWaitCommitEffect::Unknown();
1689	      }
1690	      return {};
1691	    }
1692	
1693	  private:
1694	    DeterministicNoWaitCommitEffect
1695	    AnalyzeAttr(const AttrStmtNode *attr) const {
1696	      if (PipelineRewriter::IsAsyncWaitQueueScope(attr) ||
1697	          PipelineRewriter::IsAsyncWaitInflightCount(attr)) {
1698	        return DeterministicNoWaitCommitEffect::Wait();
1699	      }
1700	      if (PipelineRewriter::IsAsyncCommitQueueScope(attr)) {
1701	        auto effect = Analyze(attr->body);
1702	        if (!effect.deterministic) {
1703	          return effect;
1704	        }
1705	        ++effect.commit_groups;
1706	        return effect;
1707	      }
1708	      return Analyze(attr->body);
1709	    }
1710	
1711	    DeterministicNoWaitCommitEffect AnalyzeFor(const ForNode *for_node) const {
1712	      if (for_node->thread_binding.defined()) {
1713	        return DeterministicNoWaitCommitEffect::Unknown();
1714	      }
1715	      const int64_t *extent_imm = as_const_int(for_node->extent);
1716	      if (extent_imm == nullptr || *extent_imm < 0) {
1717	        return DeterministicNoWaitCommitEffect::Unknown();
1718	      }
1719	      auto effect = Analyze(for_node->body);
1720	      if (!effect.deterministic) {
1721	        return effect;
1722	      }
1723	      effect.commit_groups *= static_cast<int>(*extent_imm);
1724	      return effect;
1725	    }
1726	
1727	    static DeterministicNoWaitCommitEffect
1728	    Combine(const DeterministicNoWaitCommitEffect &lhs,
1729	            const DeterministicNoWaitCommitEffect &rhs) {
1730	      if (!lhs.deterministic || !rhs.deterministic) {
1731	        return DeterministicNoWaitCommitEffect::Unknown();
1732	      }
1733	      DeterministicNoWaitCommitEffect effect;
1734	      effect.has_wait = lhs.has_wait || rhs.has_wait;
1735	      effect.commit_groups = lhs.commit_groups + rhs.commit_groups;
1736	      return effect;
1737	    }
1738	
1739	    const PipelineRewriter *rewriter_;
1740	  };
