1897	  bool ContainsAsyncSyncScopes(const Stmt &stmt) const {
1898	    bool found = false;
1899	    PostOrderVisit(stmt, [&](const ObjectRef &obj) {
1900	      if (found) {
1901	        return;
1902	      }
1903	      if (const auto *attr = obj.as<AttrStmtNode>()) {
1904	        if (IsAsyncCommitQueueScope(attr) || IsAsyncWaitQueueScope(attr)) {
1905	          found = true;
1906	        }
1907	      }
1908	    });
1909	    return found;
1910	  }
1911	
1912	  bool ContainsAsyncCommitScopes(const Stmt &stmt) const {
1913	    bool found = false;
1914	    PostOrderVisit(stmt, [&](const ObjectRef &obj) {
1915	      if (found) {
1916	        return;
1917	      }
1918	      if (const auto *attr = obj.as<AttrStmtNode>()) {
1919	        if (IsAsyncCommitQueueScope(attr)) {
1920	          found = true;
1921	        }
1922	      }
1923	    });
1924	    return found;
1925	  }
