1927	  AsyncSyncSummary SummarizeAsyncSyncScopes(const Stmt &stmt) const {
1928	    AsyncSyncSummary summary;
1929	    PostOrderVisit(stmt, [&](const ObjectRef &obj) {
1930	      if (const auto *attr = obj.as<AttrStmtNode>()) {
1931	        if (IsAsyncCommitQueueScope(attr)) {
1932	          ++summary.commit;
1933	        } else if (IsAsyncWaitQueueScope(attr)) {
1934	          ++summary.wait;
1935	        }
1936	      }
1937	    });
1938	    return summary;
1939	  }
