1942	  TryGetDeterministicNoWaitCommitGroups(const Stmt &stmt) const {
1943	    auto effect = DeterministicNoWaitCommitAnalyzer(this).Analyze(stmt);
1944	    if (!effect.deterministic || effect.has_wait) {
1945	      return std::nullopt;
1946	    }
1947	    return effect.commit_groups;
