1950	  int GuaranteedNewGroupsBeforeNextWait(const Array<Stmt> &body,
1951	                                        int start_idx) const {
1952	    int guaranteed_groups = 0;
1953	    for (int i = start_idx, n = static_cast<int>(body.size()); i < n; ++i) {
1954	      AsyncSyncSummary summary = SummarizeAsyncSyncScopes(body[i]);
1955	      if (summary.wait > 0) {
1956	        break;
1957	      }
1958	      if (summary.commit == 0) {
1959	        continue;
1960	      }
1961	      if (auto commits = TryGetDeterministicNoWaitCommitGroups(body[i])) {
1962	        guaranteed_groups += *commits;
1963	        continue;
1964	      }
1965	      break;
1966	    }
1967	    return guaranteed_groups;
1968	  }
