109	void BufferRegionCollector::HandleTileOp(const TileOperator &tile_op) {
110	  if (tile_op.as<RegionOpNode>()) {
111	    return;
112	  }
113	  if (const auto *parallel = tile_op.as<ParallelOpNode>()) {
114	    BufferRegionCollector nested(buffer_data_to_buffer_, target_);
115	    nested(parallel->GetRoot());
116	    reads_.insert(reads_.end(), nested.GetReads().begin(),
117	                  nested.GetReads().end());
118	    writes_.insert(writes_.end(), nested.GetWrites().begin(),
119	                   nested.GetWrites().end());
120	    is_global_copy_pattern_ =
121	        is_global_copy_pattern_ || nested.GetGlobalCopyPattern();
122	    is_tma_copy_ = is_tma_copy_ || nested.GetTmaCopyPattern();
123	    has_non_copy_tile_op_ = has_non_copy_tile_op_ || nested.HasNonCopyTileOp();
124	    return;
125	  }
126	  AccessRegions access = tile_op->GetAccessRegions();
127	  reads_.insert(reads_.end(), access.reads.begin(), access.reads.end());
128	  writes_.insert(writes_.end(), access.writes.begin(), access.writes.end());
129	  if (const auto *copy = tile_op.as<CopyNode>()) {
130	    if (IsGlobalLikeBuffer(copy->src) && IsSharedBuffer(copy->dst)) {
131	      is_global_copy_pattern_ = true;
132	    }
133	  }
134	  // Im2Col always uses TMA on Hopper.
135	  if (const auto *im2col = tile_op.as<Im2ColOpNode>()) {
136	    if (IsGlobalLikeBuffer(im2col->src_) && IsSharedBuffer(im2col->dst_)) {
137	      is_global_copy_pattern_ = true;
138	      if (TargetIsHopper(target_)) {
139	        is_tma_copy_ = true;
140	      }
141	    }
142	    return;
143	  }
144	  if (!tile_op.as<CopyNode>()) {
145	    has_non_copy_tile_op_ = true;
146	  }
147	}
148	
149	void BufferRegionCollector::VisitStmt_(const BufferStoreNode *op) {
150	  Buffer store_buffer = op->buffer;
151	  Array<PrimExpr> indices = op->indices;
152	  // convert indices to region
153	  Array<Range> region;
154	  for (const auto &index : indices) {
155	    region.push_back(Range::FromMinExtent(index, 1));
156	  }
157	  auto store_region = BufferRegion(store_buffer, region);
158	  writes_.push_back(store_region);
159	
160	  is_global_read_ = false;
161	  this->VisitExpr(op->value);
162	  if (is_global_read_ && IsSharedBuffer(store_buffer)) {
163	    is_global_copy_pattern_ = true;
164	  }
165	  is_global_read_ = false;
166	}
167	
168	void BufferRegionCollector::VisitExpr_(const BufferLoadNode *op) {
169	  auto load_buffer = op->buffer;
170	  Array<PrimExpr> indices = op->indices;
171	  // convert indices to region
172	  Array<Range> region;
173	  for (const auto &index : indices) {
174	    region.push_back(Range::FromMinExtent(index, 1));
175	  }
176	  auto load_region = BufferRegion(load_buffer, region);
177	  reads_.push_back(load_region);
178	
179	  if (IsGlobalLikeBuffer(op->buffer) && !within_condition_expr_) {
180	    // skip condition expr of if_then_else node
181	    // shared[i] = T.if_then_else(global[i] < n, register_a[i], register_b[i])
182	    // is not a global read shared[i] = T.if_then_else(global[i] < n,
183	    // global_a[i], global_b[i]) is a global read
184	    is_global_read_ = true;
185	  }
186	}
187	
188	void BufferRegionCollector::VisitExpr_(const CallNode *op) {
189	  if (auto tile_op = ParseOperator(GetRef<Call>(op)); tile_op.defined()) {
190	    HandleTileOp(tile_op);
191	    StmtExprVisitor::VisitExpr_(op);
192	    return;
193	  }
194	  if (op->op.same_as(builtin::address_of())) {
195	    BufferRegion buffer_region;
196	    if (const auto *load = op->args[0].as<BufferLoadNode>()) {
197	      buffer_region = BufferRegion::FullRegion(load->buffer);
198	    } else if (const auto *var_node = op->args[0].as<VarNode>()) {
199	      Var data_var = GetRef<Var>(var_node);
200	      auto it = buffer_data_to_buffer_.find(data_var);
201	      if (it != buffer_data_to_buffer_.end()) {
202	        buffer_region = BufferRegion::FullRegion((*it).second);
203	      }
204	    }
205	    if (buffer_region.defined()) {
206	      // because we only care about the buffer itself instead of indices
207	      reads_.push_back(buffer_region);
208	    }
209	  } else if (op->op.same_as(tl::access_ptr())) {
210	    ICHECK_EQ(op->args.size(), 3U);
211	    const auto *load = op->args[0].as<BufferLoadNode>();
212	    ICHECK(load) << "tl.access_ptr base must be a BufferLoad";
213	    const BufferRegion buffer_region = BufferRegion::FullRegion(load->buffer);
214	    const int access_mask = GetConservativeAccessMask(op->args[2]);
215	    // because we only care about the buffer itself instead of indices
216	    if (access_mask & kAccessRead) {
217	      reads_.push_back(buffer_region);
218	    }
219	    if (access_mask & kAccessWrite) {
220	      writes_.push_back(buffer_region);
221	    }
222	    for (const PrimExpr &index : load->indices) {
223	      this->VisitExpr(index);
224	    }
225	    if (load->predicate.defined()) {
226	      this->VisitExpr(load->predicate.value());
227	    }
228	    this->VisitExpr(op->args[1]);
229	    this->VisitExpr(op->args[2]);
230	  } else if (op->op.same_as(builtin::tvm_access_ptr())) {
231	    const VarNode *buffer_var = op->args[1].as<VarNode>();
232	    ICHECK(buffer_var);
233	    auto it = buffer_data_to_buffer_.find(GetRef<Var>(buffer_var));
234	    if (it != buffer_data_to_buffer_.end()) {
235	      const Buffer &buffer = (*it).second;
236	      const BufferRegion buffer_region = BufferRegion::FullRegion(buffer);
237	      const int access_mask = op->args.size() == 5U
238	                                  ? GetConservativeAccessMask(op->args[4])
239	                                  : kAccessReadWrite;
240	      // because we only care about the buffer itself instead of indices
241	      if (access_mask & kAccessRead) {
242	        reads_.push_back(buffer_region);
243	      }
244	      if (access_mask & kAccessWrite) {
245	        writes_.push_back(buffer_region);
246	      }
247	    }
248	    for (size_t i = 2; i < op->args.size(); ++i) {
249	      this->VisitExpr(op->args[i]);
250	    }
251	  } else if (op->op.same_as(builtin::if_then_else())) {
252	    within_condition_expr_ = true;
253	    this->VisitExpr(op->args[0]);
254	    within_condition_expr_ = false;
255	    for (auto i = 1; i < op->args.size(); i++) {
256	      this->VisitExpr(op->args[i]);
257	    }
258	  } else {
259	    StmtExprVisitor::VisitExpr_(op);
260	  }
261	}
262	
263	void BufferRegionCollector::VisitStmt_(const IfThenElseNode *op) {
264	  within_condition_expr_ = true;
265	  this->VisitExpr(op->condition);
266	  within_condition_expr_ = false;
267	  this->VisitStmt(op->then_case);
268	  if (op->else_case.defined()) {
269	    within_condition_expr_ = true;
270	    this->VisitStmt(op->else_case.value());
271	    within_condition_expr_ = false;
272	  }
273	}
