309	  struct ScheduledStmtAnalysis {
310	    size_t original_stmt_count{0};
311	    size_t stage_stmt_count{0};
312	    Array<Stmt> scheduled_stmts;
313	    std::vector<size_t> scheduled_indices;
314	    std::vector<size_t> scheduled_stage_indices;
315	    Array<Integer> replayable_bind_mask;
316	  };
317	
318	  ScheduledStmtAnalysis AnalyzeScheduledStmts(const Array<Stmt> &stmts) const {
319	    BufferSet pipeline_write_buffers = CollectPipelineWriteBuffers(stmts);
320	    ScheduledStmtAnalysis analysis;
321	    analysis.original_stmt_count = stmts.size();
322	    analysis.replayable_bind_mask.reserve(stmts.size());
323	    size_t stage_stmt_index = 0;
324	    for (size_t i = 0; i < stmts.size(); ++i) {
325	      const Stmt &stmt = stmts[i];
326	      if (IsPipelineDeclarationStmt(stmt)) {
327	        continue;
328	      }
329	      bool replayable =
330	          IsReplayableScalarBindStmt(stmt, pipeline_write_buffers);
331	      analysis.replayable_bind_mask.push_back(Integer(replayable ? 1 : 0));
332	      if (replayable) {
333	        ++stage_stmt_index;
334	        continue;
335	      }
336	      analysis.scheduled_indices.push_back(i);
337	      analysis.scheduled_stage_indices.push_back(stage_stmt_index);
338	      analysis.scheduled_stmts.push_back(stmt);
339	      ++stage_stmt_index;
340	    }
341	    analysis.stage_stmt_count = stage_stmt_index;
342	    return analysis;
343	  }
344	
345	  Array<Integer> FilterAnnotationsForScheduledStmts(
346	      const Array<Integer> &annotations,
347	      const ScheduledStmtAnalysis &analysis) const {
348	    if (annotations.size() == analysis.scheduled_stmts.size()) {
349	      return annotations;
350	    }
351	
352	    Array<Integer> filtered;
353	    if (annotations.size() == analysis.stage_stmt_count) {
354	      for (size_t index : analysis.scheduled_stage_indices) {
355	        filtered.push_back(annotations[index]);
356	      }
357	    } else {
358	      ICHECK_EQ(annotations.size(), analysis.original_stmt_count)
359	          << "PipelinePlanning: expected pipeline annotation size to match "
360	             "the scheduled statement count, executable statement count, or "
361	             "original statement count";
362	      for (size_t index : analysis.scheduled_indices) {
363	        filtered.push_back(annotations[index]);
364	      }
365	    }
366	    ICHECK_EQ(filtered.size(), analysis.scheduled_stmts.size());
367	    return filtered;
368	  }
