410	/*! \brief Information about a pipeline stage
411	 *
412	 * \param reads Array of buffer regions read by this stage
413	 * \param writes Array of buffer regions written by this stage
414	 * \param original_stmt_index Original position of this stage in the pipeline
415	 * before reordering \param order Current position of this stage in the
416	 * pipeline after reordering (-1 if not yet assigned) \param stage Pipeline
417	 * stage number this operation belongs to (-1 if not yet assigned) \param
418	 * copy_stage Whether this stage is a memory copy operation \param
419	 * last_use_stmt_index Index of the last statement (in original order) that
420	 * uses the results of this stage (-1 if not yet determined). This field is
421	 * crucial for pipeline optimization:
422	 * - For copy stages: indicates the index of the last statement that reads
423	 * from the copied data, helping determine optimal placement of copy
424	 * operations
425	 * - Used to ensure copy operations are scheduled before their consumers
426	 * - A value of -1 means no subsequent statement uses this stage's output
427	 * - This information enables better pipeline scheduling by minimizing data
428	 *   dependencies and maximizing parallelism
429	 */
430	struct PipelineStageInfo {
431	  Array<BufferRegion> reads, writes;
432	  std::unordered_set<const VarNode *> scalar_defs;
433	  std::unordered_set<const VarNode *> scalar_uses;
434	  int original_stmt_index{};
435	  int order = -1, stage = -1;
436	  bool copy_stage = false;
437	  bool tma_copy = false; // true if this copy stage uses TMA (not cp.async)
438	  bool conditional_execution = false;
439	  bool producer_for_copy = false;
440	  int last_use_stmt_index =
441	      -1; // Initialized to -1, indicating no consumers found yet
442	
443	public:
444	  bool IsFirstStage() const { return copy_stage || producer_for_copy; }
445	  bool IsCopyStage() const { return copy_stage; }
446	  bool IsTmaCopy() const { return tma_copy; }
447	  bool IsProducerForCopy() const { return producer_for_copy; }
448	  bool IsLastUseStmtIndexValid() const { return last_use_stmt_index != -1; }
449	};
