481	  bool MayBeConditionallyExecuted(const Stmt &stmt) const {
482	    bool conditional = false;
483	    PostOrderVisit(stmt, [&](const ObjectRef &node) {
484	      if (conditional) {
485	        return;
486	      }
487	      if (const auto *if_then_else = node.as<IfThenElseNode>()) {
488	        conditional = true;
489	        return;
490	      }
491	      if (const auto *realize = node.as<SBlockRealizeNode>()) {
492	        if (!is_one(realize->predicate)) {
493	          conditional = true;
494	        }
495	      }
496	    });
497	    return conditional;
498	  }
