510	  bool IsPureCopyStmt(const Stmt &stmt) const {
511	    auto is_global_like_buffer = [](const Buffer &buffer) {
512	      return IsGlobalBuffer(buffer) ||
513	             (buffer.defined() && buffer.scope().empty());
514	    };
515	    auto is_pure_raw_copy_value = [&](const PrimExpr &expr,
516	                                      const auto &self) -> bool {
517	      if (const auto *load = expr.as<BufferLoadNode>()) {
518	        return is_global_like_buffer(load->buffer);
519	      }
520	      if (const auto *cast = expr.as<CastNode>()) {
521	        return self(cast->value, self);
522	      }
523	      return false;
524	    };
525	
526	    bool saw_copy = false;
527	    bool saw_non_copy_tile_op = false;
528	    bool saw_non_copy_buffer_store = false;
529	    PostOrderVisit(stmt, [&](const ObjectRef &node) {
530	      if (saw_non_copy_tile_op || saw_non_copy_buffer_store) {
531	        return;
532	      }
533	      if (const auto *store = node.as<BufferStoreNode>()) {
534	        saw_copy = true;
535	        if ((!IsSharedBuffer(store->buffer) &&
536	             !IsLocalBuffer(store->buffer, /*allow_var=*/true)) ||
537	            !is_pure_raw_copy_value(store->value, is_pure_raw_copy_value)) {
538	          saw_non_copy_buffer_store = true;
539	        }
540	        return;
541	      }
542	      const auto *call = node.as<CallNode>();
543	      if (call == nullptr) {
544	        return;
545	      }
546	      auto tile_op = ParseOperator(GetRef<Call>(call));
547	      if (!tile_op.defined()) {
548	        return;
549	      }
550	      if (tile_op.as<RegionOpNode>()) {
551	        return;
552	      }
553	      if (const auto *parallel = tile_op.as<ParallelOpNode>()) {
554	        if (IsPureCopyStmt(parallel->GetRoot())) {
555	          saw_copy = true;
556	        } else {
557	          saw_non_copy_tile_op = true;
558	        }
559	        return;
560	      }
561	      if (tile_op.as<CopyNode>() || tile_op.as<Im2ColOpNode>()) {
562	        saw_copy = true;
563	      } else {
564	        saw_non_copy_tile_op = true;
565	      }
566	    });
567	    return saw_copy && !saw_non_copy_tile_op && !saw_non_copy_buffer_store;
568	  }
