570	  Optional<TileOperator> GetSinglePureCopyTileOp(const Stmt &stmt) const {
571	    Optional<TileOperator> copy_tile_op;
572	    bool saw_non_copy_tile_op = false;
573	    bool saw_multiple_copy_ops = false;
574	    PostOrderVisit(stmt, [&](const ObjectRef &node) {
575	      if (saw_non_copy_tile_op || saw_multiple_copy_ops) {
576	        return;
577	      }
578	      const auto *call = node.as<CallNode>();
579	      if (call == nullptr) {
580	        return;
581	      }
582	      auto tile_op = ParseOperator(GetRef<Call>(call));
583	      if (!tile_op.defined()) {
584	        return;
585	      }
586	      if (tile_op.as<RegionOpNode>()) {
587	        return;
588	      }
589	      if (tile_op.as<CopyNode>() || tile_op.as<Im2ColOpNode>()) {
590	        if (copy_tile_op.defined()) {
591	          saw_multiple_copy_ops = true;
592	          copy_tile_op = Optional<TileOperator>();
593	        } else {
594	          copy_tile_op = tile_op;
595	        }
596	      } else {
597	        saw_non_copy_tile_op = true;
598	        copy_tile_op = Optional<TileOperator>();
599	      }
600	    });
601	    if (saw_non_copy_tile_op || saw_multiple_copy_ops) {
602	      return Optional<TileOperator>();
603	    }
604	    return copy_tile_op;
605	  }
