612	  void ClassifyCopyLikeStage(const Stmt &stmt, PipelineStageInfo *pinfo) const {
613	    ICHECK(pinfo != nullptr);
614	    if (pinfo->conditional_execution) {
615	      return;
616	    }
617	
618	    if (pinfo->copy_stage) {
619	      return;
620	    }
621	
622	    auto copy_tile_op = GetSinglePureCopyTileOp(stmt);
623	    if (!copy_tile_op.defined()) {
624	      return;
625	    }
626	
627	    if (const auto *copy = copy_tile_op.value().as<CopyNode>()) {
628	      if (!IsGlobalLikeBuffer(copy->src) || !IsSharedBuffer(copy->dst)) {
629	        return;
630	      }
631	      pinfo->copy_stage = true;
632	      return;
633	    }
634	
635	    if (const auto *im2col = copy_tile_op.value().as<Im2ColOpNode>()) {
636	      if (!IsGlobalLikeBuffer(im2col->src_) || !IsSharedBuffer(im2col->dst_)) {
637	        return;
638	      }
639	      pinfo->copy_stage = true;
640	      pinfo->tma_copy = TargetIsHopper(target_);
641	    }
642	  }
643	
644	  void AnalyzeCopyLastUse(
645	      std::vector<PipelineStageInfo> *pipeline_stage_infos) const {
646	    for (auto &pinfo : *pipeline_stage_infos) {
647	      if (!pinfo.IsFirstStage()) {
648	        continue;
649	      }
650	
651	      for (int i = pinfo.original_stmt_index + 1;
652	           i < static_cast<int>(pipeline_stage_infos->size()); ++i) {
653	        for (const BufferRegion &read : (*pipeline_stage_infos)[i].reads) {
654	          if (std::find_if(pinfo.writes.begin(), pinfo.writes.end(),
655	                           [&](const BufferRegion &r) {
656	                             return r->buffer == read->buffer &&
657	                                    MayConflict(r->region, read->region);
658	                           }) != pinfo.writes.end()) {
659	            pinfo.last_use_stmt_index = std::max(pinfo.last_use_stmt_index, i);
660	          }
661	        }
662	
663	        if (!pinfo.IsCopyStage()) {
664	          continue;
665	        }
666	
667	        for (const BufferRegion &write : (*pipeline_stage_infos)[i].writes) {
668	          if (std::find_if(pinfo.writes.begin(), pinfo.writes.end(),
669	                           [&](const BufferRegion &r) {
670	                             return r->buffer == write->buffer &&
671	                                    MayConflict(r->region, write->region);
672	                           }) != pinfo.writes.end()) {
673	            LOG(FATAL) << "Pipeline planning error: Multiple writes to "
674	                          "overlapping buffer regions detected. "
675	                       << "Stage " << pinfo.original_stmt_index << " and stage "
676	                       << i << " are both writing to buffer '"
677	                       << write->buffer->name
678	                       << "' with overlapping regions. This is not supported "
679	                          "in pipeline planning.";
680	          }
681	        }
682	      }
683	    }
684	  }
685	
686	  void PropagateBufferProducersForCopy(
687	      std::vector<PipelineStageInfo> *pipeline_stage_infos) const {
688	    struct CopyStageDependencyReadsManager {
689	      std::vector<BufferRegion> regions;
690	
691	      void AddUnique(const BufferRegion &region) {
692	        for (const BufferRegion &copy_read : regions) {
693	          if (region->buffer.same_as(copy_read->buffer)) {
694	            return;
695	          }
696	        }
697	        regions.push_back(region);
698	      }
699	
700	      bool Contains(const BufferRegion &region) const {
701	        for (const BufferRegion &copy_read : regions) {
702	          if (region->buffer.same_as(copy_read->buffer)) {
703	            return true;
704	          }
705	        }
706	        return false;
707	      }
708	
709	      size_t Size() const { return regions.size(); }
710	    };
711	
712	    CopyStageDependencyReadsManager copy_stage_dependency_reads_mgr;
713	
714	    for (const auto &pinfo : *pipeline_stage_infos) {
715	      if (pinfo.IsCopyStage()) {
716	        for (const BufferRegion &read : pinfo.reads) {
717	          copy_stage_dependency_reads_mgr.AddUnique(read);
718	        }
719	      }
720	    }
721	
722	    const size_t max_iterations = (pipeline_stage_infos->size() * 4) + 16;
723	    size_t iter_count = 0;
724	
725	    for (auto &pinfo : *pipeline_stage_infos) {
726	      if (!pinfo.IsCopyStage()) {
727	        continue;
728	      }
729	      auto original_copy_stmt_index = pinfo.original_stmt_index;
730	      bool updated = true;
731	      while (updated) {
732	        updated = false;
733	        for (auto &pinfo_inner : *pipeline_stage_infos) {
734	          if (pinfo_inner.IsCopyStage()) {
735	            continue;
736	          }
737	          if (pinfo_inner.original_stmt_index >= original_copy_stmt_index) {
738	            break;
739	          }
740	
741	          bool should_prepare = false;
742	          for (const BufferRegion &write : pinfo_inner.writes) {
743	            if (copy_stage_dependency_reads_mgr.Contains(write)) {
744	              should_prepare = true;
745	              break;
746	            }
747	          }
748	          if (should_prepare && !pinfo_inner.IsProducerForCopy()) {
749	            pinfo_inner.producer_for_copy = true;
750	            updated = true;
751	          }
752	          if (should_prepare) {
753	            for (const BufferRegion &read : pinfo_inner.reads) {
754	              size_t before = copy_stage_dependency_reads_mgr.Size();
755	              copy_stage_dependency_reads_mgr.AddUnique(read);
756	              if (copy_stage_dependency_reads_mgr.Size() > before) {
757	                updated = true;
758	              }
759	            }
760	          }
761	        }
762	        iter_count++;
763	        if (iter_count > max_iterations) {
764	          LOG(FATAL)
765	              << "Pipeline planning: Exceeded maximum iterations ("
766	              << max_iterations << ") in copy stage dependency propagation. "
767	              << "This may indicate a cyclic or pathological dependency graph.";
768	        }
769	      }
770	    }
771	  }
772	
773	  std::unordered_map<const VarNode *, int> BuildScalarDefMap(
774	      const std::vector<PipelineStageInfo> &pipeline_stage_infos) const {
775	    std::unordered_map<const VarNode *, int> scalar_def_to_stmt;
776	    for (int i = 0; i < static_cast<int>(pipeline_stage_infos.size()); ++i) {
777	      for (const VarNode *var : pipeline_stage_infos[i].scalar_defs) {
778	        scalar_def_to_stmt.emplace(var, i);
779	      }
780	    }
781	    return scalar_def_to_stmt;
782	  }
783	
784	  void PropagateScalarProducersForCopy(
785	      std::vector<PipelineStageInfo> *pipeline_stage_infos) const {
786	    auto scalar_def_to_stmt = BuildScalarDefMap(*pipeline_stage_infos);
787	    const size_t max_iterations = (pipeline_stage_infos->size() * 4) + 16;
788	    size_t iter_count = 0;
789	    bool updated = true;
790	
791	    auto update_producer = [](PipelineStageInfo *producer,
792	                              int consumer_last_use) -> bool {
793	      if (consumer_last_use < 0) {
794	        return false;
795	      }
796	      bool changed = false;
797	      if (!producer->producer_for_copy) {
798	        producer->producer_for_copy = true;
799	        producer->last_use_stmt_index = consumer_last_use;
800	        changed = true;
801	      } else if (!producer->IsLastUseStmtIndexValid() ||
802	                 consumer_last_use < producer->last_use_stmt_index) {
803	        producer->last_use_stmt_index = consumer_last_use;
804	        changed = true;
805	      }
806	      return changed;
807	    };
808	
809	    while (updated) {
810	      updated = false;
811	      for (int consumer_idx = 0;
812	           consumer_idx < static_cast<int>(pipeline_stage_infos->size());
813	           ++consumer_idx) {
814	        const auto &consumer = (*pipeline_stage_infos)[consumer_idx];
815	        if (!(consumer.IsFirstStage() && consumer.IsLastUseStmtIndexValid())) {
816	          continue;
817	        }
818	        for (const VarNode *var : consumer.scalar_uses) {
819	          auto it = scalar_def_to_stmt.find(var);
820	          if (it == scalar_def_to_stmt.end() || it->second == consumer_idx) {
821	            continue;
822	          }
823	          auto &producer = (*pipeline_stage_infos)[it->second];
824	          if (producer.IsCopyStage()) {
825	            continue;
826	          }
827	          updated |= update_producer(&producer, consumer.last_use_stmt_index);
828	        }
829	      }
830	      if (++iter_count > max_iterations) {
831	        LOG(FATAL) << "Pipeline planning: Exceeded maximum iterations while "
832	                      "propagating scalar producers for copy stages.";
833	      }
834	    }
835	  }
836	
837	  void ValidateScalarDependencies(
838	      const std::vector<PipelineStageInfo> &pipeline_stage_infos) const {
839	    auto scalar_def_to_stmt = BuildScalarDefMap(pipeline_stage_infos);
840	    for (int consumer_idx = 0;
841	         consumer_idx < static_cast<int>(pipeline_stage_infos.size());
842	         ++consumer_idx) {
843	      const auto &consumer = pipeline_stage_infos[consumer_idx];
844	      for (const VarNode *var : consumer.scalar_uses) {
845	        auto it = scalar_def_to_stmt.find(var);
846	        if (it == scalar_def_to_stmt.end() || it->second == consumer_idx) {
847	          continue;
848	        }
849	        const auto &producer = pipeline_stage_infos[it->second];
850	        ICHECK_EQ(producer.stage, consumer.stage)
851	            << "Pipeline planning error: scalar dependency from statement "
852	            << producer.original_stmt_index << " to statement "
853	            << consumer.original_stmt_index
854	            << " crosses pipeline stages. Scheduled scalar Bind statements "
855	               "must stay in the same stage as their consumers.";
856	        if (producer.stage == consumer.stage) {
857	          ICHECK_LT(producer.order, consumer.order)
858	              << "Pipeline planning error: scalar dependency from statement "
859	              << producer.original_stmt_index << " to statement "
860	              << consumer.original_stmt_index
861	              << " is reordered within the same pipeline stage.";
862	        }
863	      }
864	    }
865	  }
866	
867	  bool EmitImplicitAsyncAnnotations(
868	      const std::vector<PipelineStageInfo> &pipeline_stage_infos,
869	      Map<String, Any> *annotations) const {
870	    if (!TargetHasAsyncCopy(target_) || !use_async_copy_) {
871	      return false;
872	    }
873	
874	    std::vector<int> async_group_ids(pipeline_stage_infos.size(), -1);
875	    std::vector<int> stmt_indices_by_order(pipeline_stage_infos.size());
876	    std::iota(stmt_indices_by_order.begin(), stmt_indices_by_order.end(), 0);
877	    std::stable_sort(stmt_indices_by_order.begin(), stmt_indices_by_order.end(),
878	                     [&](int lhs, int rhs) {
879	                       if (pipeline_stage_infos[lhs].order !=
880	                           pipeline_stage_infos[rhs].order) {
881	                         return pipeline_stage_infos[lhs].order <
882	                                pipeline_stage_infos[rhs].order;
883	                       }
884	                       return lhs < rhs;
885	                     });
886	
887	    int next_async_group_id = 0;
888	    std::map<std::pair<int, int>, int> implicit_group_ids;
889	    for (int stmt_idx : stmt_indices_by_order) {
890	      const auto &pinfo = pipeline_stage_infos[stmt_idx];
891	      if (!IsAsyncProducerCandidate(pinfo)) {
892	        continue;
893	      }
894	      auto key = std::make_pair(pinfo.stage, pinfo.last_use_stmt_index);
895	      auto [it, inserted] =
896	          implicit_group_ids.emplace(key, next_async_group_id);
897	      if (inserted) {
898	        ++next_async_group_id;
899	      }
900	      async_group_ids[stmt_idx] = it->second;
901	    }
902	
903	    if (next_async_group_id == 0) {
904	      return false;
905	    }
906	
907	    std::vector<Integer> async_producers;
908	    std::vector<Integer> async_producer_groups;
909	    async_producers.reserve(pipeline_stage_infos.size());
910	    async_producer_groups.reserve(pipeline_stage_infos.size());
911	    std::unordered_set<int> async_stage_ids;
912	    for (size_t i = 0; i < pipeline_stage_infos.size(); ++i) {
913	      bool is_async_producer = async_group_ids[i] != -1;
914	      async_producers.push_back(Integer(is_async_producer ? 1 : 0));
915	      async_producer_groups.push_back(Integer(async_group_ids[i]));
916	      if (is_async_producer) {
917	        async_stage_ids.insert(pipeline_stage_infos[i].stage);
918	      }
919	    }
920	
921	    annotations->Set(kPipelineAsyncProducers, Array<Integer>(async_producers));
922	    annotations->Set(kPipelineAsyncProducerGroups,
923	                     Array<Integer>(async_producer_groups));
924	
925	    std::vector<int> sorted_async_stage_ids(async_stage_ids.begin(),
926	                                            async_stage_ids.end());
927	    std::sort(sorted_async_stage_ids.begin(), sorted_async_stage_ids.end());
928	    std::vector<Integer> async_stages;
929	    async_stages.reserve(sorted_async_stage_ids.size());
930	    for (int stage_id : sorted_async_stage_ids) {
931	      async_stages.push_back(Integer(stage_id));
932	    }
933	    annotations->Set(s_tir::attr::software_pipeline_async_stages,
934	                     Array<Integer>(async_stages));
935	    return true;
936	  }
937	
938	  void MaybeAnnotateLegacyAsyncPipelineLoop(const Array<Stmt> &pipeline_stmts,
939	                                            const Array<Integer> &order_array,
940	                                            const Array<Integer> &stage_array,
941	                                            Map<String, Any> *annotations) {
942	    if (!TargetHasAsyncCopy(target_) || !use_async_copy_) {
943	      return;
944	    }
945	    ICHECK_EQ(pipeline_stmts.size(), order_array.size());
946	    ICHECK_EQ(pipeline_stmts.size(), stage_array.size());
947	
948	    std::vector<PipelineStageInfo> pipeline_stage_infos;
949	    pipeline_stage_infos.reserve(pipeline_stmts.size());
950	    for (size_t i = 0; i < pipeline_stmts.size(); ++i) {
951	      auto pinfo = MakePipelineStageInfo(pipeline_stmts[i], i);
952	      ClassifyCopyLikeStage(pipeline_stmts[i], &pinfo);
953	      pinfo.order = static_cast<int>(order_array[i]->value);
954	      pinfo.stage = static_cast<int>(stage_array[i]->value);
955	      if (!pinfo.IsCopyStage() && !pinfo.conditional_execution &&
956	          pinfo.stage == 0) {
957	        bool reads_global = false;
958	        bool writes_shared = false;
959	        for (const BufferRegion &read : pinfo.reads) {
960	          if (IsGlobalLikeBuffer(read->buffer)) {
961	            reads_global = true;
962	            break;
963	          }
964	        }
965	        for (const BufferRegion &write : pinfo.writes) {
966	          if (IsSharedBuffer(write->buffer)) {
967	            writes_shared = true;
968	            break;
969	          }
970	        }
971	        if (reads_global && writes_shared) {
972	          pinfo.copy_stage = true;
973	        }
974	      }
975	      pipeline_stage_infos.push_back(std::move(pinfo));
976	    }
977	
978	    AnalyzeCopyLastUse(&pipeline_stage_infos);
979	    EmitImplicitAsyncAnnotations(pipeline_stage_infos, annotations);
980	  }
981	
982	  PipelineStageInfo MakePipelineStageInfo(Stmt stmt, int idx) {
983	    SBlock block(/*iter_vars=*/{}, /*reads=*/{}, /*writes=*/{},
984	                 /*name_hint=*/"",
985	                 /*body*/ std::move(stmt));
986	    auto collector = BufferRegionCollector(buffer_data_to_buffer_, target_);
987	    collector(block);
988	    PipelineStageInfo pinfo;
989	    pinfo.reads = std::move(collector.GetReads());
990	    pinfo.writes = std::move(collector.GetWrites());
991	    auto [scalar_defs, scalar_uses] =
992	        ScalarUseDefCollector::Collect(block->body);
993	    pinfo.scalar_defs = std::move(scalar_defs);
994	    pinfo.scalar_uses = std::move(scalar_uses);
995	    pinfo.original_stmt_index = idx;
996	    pinfo.conditional_execution = MayBeConditionallyExecuted(block->body);
997	    bool pure_copy_stage =
998	        collector.GetGlobalCopyPattern() && IsPureCopyStmt(block->body);
999	    pinfo.copy_stage = pure_copy_stage;
1000	    pinfo.tma_copy = pure_copy_stage && !pinfo.conditional_execution &&
1001	                     collector.GetTmaCopyPattern();
1002	    ClassifyCopyLikeStage(block->body, &pinfo);
1003	    return pinfo;
1004	  }
