1074	  using ScheduledStmtAnalysis =
1075	      PipelinePlanningBodyAnalyzer::ScheduledStmtAnalysis;
1076	  using SeqStmtFlattener = PipelinePlanningBodyAnalyzer::SeqStmtFlattener;
1077	
