1090	                                                                 analysis);
1091	  }
1092	
1093	  Stmt VisitStmt_(const ForNode *loop) final {
1094	    auto order_anno = loop->annotations.Get("tl_pipeline_order");
1095	    auto stage_anno = loop->annotations.Get("tl_pipeline_stage");
1096	    auto num_stages_anno = loop->annotations.Get("num_stages");
1097	    if (order_anno && stage_anno) {
1098	      auto order_array = Downcast<Array<Integer>>(order_anno.value());
1099	      auto stage_array = Downcast<Array<Integer>>(stage_anno.value());
1100	
1101	      Map<String, Any> annotations;
1102	      for (const auto &[key, value] : loop->annotations) {
1103	        if (key != "tl_pipeline_order" && key != "tl_pipeline_stage") {
1104	          annotations.Set(key, value);
1105	        }
1106	      }
1107	      if (TargetHasAsyncCopy(target_) && use_async_copy_) {
1108	        // Legacy explicit stage/order annotations do not carry per-statement
1109	        // async producer metadata yet, so keep the previous stage-level
1110	        // behavior as a fallback for these loops.
1111	        annotations.Set(s_tir::attr::software_pipeline_async_stages,
1112	                        Array<Integer>{0});
1113	      }
1114	      Array<Stmt> pipeline_body_stmts = NormalizePipelineBody(loop->body);
1115	      Array<Stmt> pipeline_stmts =
1116	          SeqStmtFlattener::Flatten(pipeline_body_stmts);
1117	      ScheduledStmtAnalysis analysis = AnalyzeScheduledStmts(pipeline_stmts);
1118	      ICHECK(!analysis.scheduled_stmts.empty())
1119	          << "PipelinePlanning: explicit pipeline annotations have no "
1120	             "schedulable statements after removing replayable scalar Bind "
1121	             "statements";
1122	      Array<Integer> filtered_order_array =
1123	          FilterAnnotationsForScheduledStmts(order_array, analysis);
1124	      Array<Integer> filtered_stage_array =
1125	          FilterAnnotationsForScheduledStmts(stage_array, analysis);
1126	      annotations.Set(s_tir::attr::software_pipeline_order,
1127	                      filtered_order_array);
1128	      annotations.Set(s_tir::attr::software_pipeline_stage,
1129	                      filtered_stage_array);
1130	      if (pipeline_stmts.size() == pipeline_body_stmts.size()) {
1131	        bool flatten_preserved_original_order = true;
1132	        for (size_t i = 0; i < pipeline_stmts.size(); ++i) {
1133	          if (!pipeline_stmts[i].same_as(pipeline_body_stmts[i])) {
1134	            flatten_preserved_original_order = false;
1135	            break;
1136	          }
1137	        }
1138	        if (flatten_preserved_original_order &&
1139	            std::any_of(analysis.replayable_bind_mask.begin(),
1140	                        analysis.replayable_bind_mask.end(),
1141	                        [](const Integer &value) { return !is_zero(value); })) {
1142	          annotations.Set(kPipelineReplayableScalarBinds,
1143	                          analysis.replayable_bind_mask);
1144	        }
1145	      }
1146	      MaybeAnnotateLegacyAsyncPipelineLoop(analysis.scheduled_stmts,
1147	                                           filtered_order_array,
1148	                                           filtered_stage_array, &annotations);
1149	      auto for_node = GetRef<For>(loop);
1150	      auto *n = for_node.CopyOnWrite();
1151	      n->annotations = annotations;
1152	      n->body = MakePipelineBody(pipeline_body_stmts);
1153	      return for_node;
1154	    }
1155	
1156	    if (!num_stages_anno)
1157	      return StmtExprMutator::VisitStmt_(loop);
1158	    int num_stages = num_stages_anno->as<IntImmNode>()->value;
1159	    // Skip software pipelining on ROCm targets where async-copy pipelining
1160	    // has not been validated.  Currently only gfx950 (CDNA4 / MI350) supports
1161	    // the full HIP async-copy pipeline path.  gfx942 (CDNA3 / MI300X) has
1162	    // async-copy hardware but the software pipeline for that target has not
1163	    // been validated yet, so it falls back to a plain sequential loop as well.
1164	    // RDNA targets have no async-copy support at all and also fall back.
1165	    if (TargetIsRocm(target_) && !TargetIsGfx950(target_) && num_stages >= 1) {
1166	      // Strip the "num_stages" annotation before recursing so that downstream
1167	      // passes (InjectSoftwarePipeline, MultiVersionBufferRewriter, etc.) do
1168	      // not treat this loop as pipelined.  Leaving the annotation in place
1169	      // would cause those passes to multi-version shared buffers and inject
1170	      // cp.async / barrier code that is incompatible with the plain sequential
1171	      // execution path chosen here.
1172	      auto stripped = GetRef<For>(loop);
1173	      Map<String, Any> annotations;
1174	      for (const auto &[key, value] : loop->annotations) {
1175	        if (key != "num_stages") {
1176	          annotations.Set(key, value);
1177	        }
1178	      }
1179	      stripped.CopyOnWrite()->annotations = annotations;
1180	      return StmtExprMutator::VisitStmt_(stripped.get());
1181	    }
1182	    Array<Stmt> pipeline_body_stmts = NormalizePipelineBody(loop->body);
1183	
1184	    ICHECK(num_stages >= 1);
1185	    ICHECK(loop->kind == ForKind::kSerial);
1186	
1187	    // Flatten nested SeqStmts so pipeline planning can assign stages to the
1188	    // normalized top-level statement list.
1189	    Array<Stmt> flat_stmts = SeqStmtFlattener::Flatten(pipeline_body_stmts);
1190	    ScheduledStmtAnalysis analysis = AnalyzeScheduledStmts(flat_stmts);
1191	    ICHECK(!analysis.scheduled_stmts.empty())
1192	        << "PipelinePlanning: loop has no schedulable statements after "
1193	           "removing replayable scalar Bind statements";
1194	
1195	    std::vector<PipelineStageInfo> pipeline_stage_infos;
1196	    for (size_t i = 0; i < analysis.scheduled_stmts.size(); i++) {
1197	      auto pinfo = MakePipelineStageInfo(analysis.scheduled_stmts[i], i);
1198	      pipeline_stage_infos.push_back(std::move(pinfo));
1199	    }
1200	
1201	    // Some statements before a copy are not copy operations themselves, but
1202	    // they prepare buffers that the copy must read.  A common example is
1203	    // producer-side initialization before a conditional or partial copy:
1204	    //
1205	    //   fill(shared, 0)        // writes shared
1206	    //   copy(global, shared)   // may rely on the initialized values
1207	    //
1208	    // If the copy is moved to the producer side, the fill must move with it;
1209	    // otherwise the copy could observe an uninitialized or wrong shared-buffer
1210	    // value.  PropagateBufferProducersForCopy computes a buffer-level backward
1211	    // dependency closure from copy-stage reads to earlier non-copy writes and
1212	    // marks those statements as `producer_for_copy`.  They then participate in
1213	    // the producer-stage scheduling just like the copy stages they prepare.
1214	    PropagateBufferProducersForCopy(&pipeline_stage_infos);
1215	
1216	    // Analysis use-def chain to determine last_use_stmt_index for copy
1217	    // operations This step is critical for pipeline optimization as it
1218	    // identifies the index of the last statement that consumes data produced by
1219	    // copy stages, enabling optimal placement of copy operations in the
1220	    // pipeline schedule.
1221	    AnalyzeCopyLastUse(&pipeline_stage_infos);
1222	
1223	    PropagateScalarProducersForCopy(&pipeline_stage_infos);
1224	
1225	    // Making stages and orders
1226	    int order_idx = 0;
1227	    // Stage 1. Create pipeline stages and assign order
1228	    for (auto &pinfo : pipeline_stage_infos) {
1229	      // Skip elements that must be in first stage:
1230	      // 1. Copy stages (with active last_use_stmt_index) - these need special
1231	      // handling
1232	      //    because they have consumers that depend on their data
1233	      // 2. All Producer stages for copy stages.
1234	      if (pinfo.IsFirstStage() && pinfo.IsLastUseStmtIndexValid()) {
1235	        continue;
1236	      }
1237	
1238	      // Main logic stage assignment:
1239	      // - Increment order index
1240	      // - Assign to new stage (current num_stages)
1241	      pinfo.order = order_idx++;
1242	      pinfo.stage = num_stages;
1243	
1244	      // Schedule copy stages that have this stage as their last consumer
1245	      // This ensures copy operations are placed right before their final
1246	      // consumer for optimal pipeline efficiency
1247	      for (auto &pinfo_1 : pipeline_stage_infos) {
1248	        if ((pinfo_1.IsFirstStage() &&
1249	             pinfo_1.last_use_stmt_index == pinfo.original_stmt_index)) {
1250	          pinfo_1.order = order_idx++;
1251	          pinfo_1.stage = 0; // Copy stages are typically assigned to stage 0
1252	        }
1253	      }
1254	    }
1255	
1256	    ICHECK(size_t(order_idx) == pipeline_stage_infos.size())
1257	        << "The number of stages should be equal to the number of pipeline "
1258	           "stages. "
1259	        << "Got " << order_idx << " stages and " << pipeline_stage_infos.size()
1260	        << " pipeline stages.";
1261	
1262	    // Step 2. if all the copy is at the end of the order, we can move these
1263	    // copy to the beginning of the order and shrink the stage offset by 1.
1264	    int copy_stage_at_end = [&]() {
1265	      int copy_stage_cnt = 0;
1266	      int copy_order_min = pipeline_stage_infos.size();
1267	      int non_copy_order_max = 0;
1268	      for (auto &pinfo : pipeline_stage_infos) {
1269	        if (pinfo.IsFirstStage()) {
1270	          copy_stage_cnt++;
1271	          copy_order_min = std::min(copy_order_min, pinfo.order);
1272	        } else {
1273	          non_copy_order_max = std::max(non_copy_order_max, pinfo.order);
1274	        }
1275	      }
1276	      if (copy_order_min > non_copy_order_max)
1277	        return copy_stage_cnt;
1278	      return -1;
1279	    }();
1280	    if (copy_stage_at_end > 0 && num_stages >= 2) {
1281	      for (auto &pinfo : pipeline_stage_infos) { // move copy to the beginning
1282	        pinfo.order =
1283	            (pinfo.order + copy_stage_at_end) % pipeline_stage_infos.size();
1284	        if (!pinfo.IsCopyStage() && !pinfo.IsProducerForCopy())
1285	          pinfo.stage--;
1286	      }
1287	    }
1288	
1289	    ValidateScalarDependencies(pipeline_stage_infos);
1290	
1291	    // Finally, make the pipeline annotation
1292	    Map<String, Any> annotations;
1293	    for (const auto &[key, value] : loop->annotations) {
1294	      if (key != "num_stages") {
1295	        annotations.Set(key, value);
1296	      }
1297	    }
1298	    // Preserve the original TileLang pipelining depth for downstream scheduling
1299	    // (e.g. generated async-copy wait placement). We intentionally do NOT
1300	    // keep the legacy key "num_stages" here because multiple downstream passes
1301	    // (e.g. internal buffer versioning / warp specialization) treat it as an
1302	    // active pipeline marker and do not support nested pipelines.
1303	    annotations.Set("tl_pipelined_num_stages", Integer(num_stages));
1304	
1305	    std::vector<Integer> orders, stages;
1306	    orders.reserve(pipeline_stage_infos.size());
1307	    stages.reserve(pipeline_stage_infos.size());
1308	    for (auto &pinfo : pipeline_stage_infos) {
1309	      orders.push_back(pinfo.order);
1310	      stages.push_back(pinfo.stage);
1311	    }
1312	
1313	    annotations.Set(s_tir::attr::software_pipeline_stage,
1314	                    Array<Integer>(stages));
1315	    annotations.Set(s_tir::attr::software_pipeline_order,
1316	                    Array<Integer>(orders));
1317	    if (std::any_of(analysis.replayable_bind_mask.begin(),
1318	                    analysis.replayable_bind_mask.end(),
1319	                    [](const Integer &value) { return !is_zero(value); })) {
1320	      annotations.Set(kPipelineReplayableScalarBinds,
1321	                      analysis.replayable_bind_mask);
1322	    }
1323	
1324	    // Propagate per-statement TMA eligibility so InjectSoftwarePipeline can
1325	    // rewrite TMA copies to use pipeline-level barrier management.
1326	    {
1327	      std::vector<Integer> tma_copies;
1328	      tma_copies.reserve(pipeline_stage_infos.size());
1329	      bool has_tma_copy = false;
1330	      for (auto &pinfo : pipeline_stage_infos) {
1331	        bool IsTmaCopy = pinfo.IsTmaCopy();
1332	        has_tma_copy = has_tma_copy || IsTmaCopy;
1333	        tma_copies.push_back(Integer(IsTmaCopy ? 1 : 0));
1334	      }
1335	      if (has_tma_copy) {
1336	        annotations.Set(kPipelineTmaCopies, Array<Integer>(tma_copies));
1337	      }
1338	    }
1339	
1340	    EmitImplicitAsyncAnnotations(pipeline_stage_infos, &annotations);
1341	
1342	    // Reconstruct the loop body with the flattened SeqStmt so that
1343	    // InjectSoftwarePipeline sees the correct number of pipeline stages.
1344	    Stmt new_body = MakePipelineBody(flat_stmts);
1345	
1346	    return For(loop->loop_var, loop->min, loop->extent, loop->kind, new_body,
1347	               loop->thread_binding, annotations);
1348	  }
1349	
1350	  Stmt VisitStmt_(const SBlockNode *op) final {
1351	    for (const auto &buffer : op->alloc_buffers) {
1352	      buffer_data_to_buffer_.Set(buffer->data, buffer);
1353	    }
1354	    SBlock block = Downcast<SBlock>(StmtExprMutator::VisitStmt_(op));
1355	    for (const auto &buffer : op->alloc_buffers) {
1356	      buffer_data_to_buffer_.erase(buffer->data);
1357	    }
1358	    return block;
1359	  }
1360	
1361	  Map<Var, Buffer> buffer_data_to_buffer_;
1362	  Target target_;
1363	  bool use_async_copy_{};
1364	};
1365	
1366	tvm::transform::Pass PipelinePlanning() {
1367	  using namespace tirx::transform;
1368	  auto pass_func = [=](PrimFunc f, const IRModule &m, PassContext ctx) {
1369	    bool use_async_copy =
1370	        ctx->GetConfig<Bool>("tirx.use_async_copy", Bool(true)).value();
1371	    PrimFuncNode *fptr = f.CopyOnWrite();
1372	    fptr->body = PipelinePlanner::Substitute(f, use_async_copy);
1373	    return f;
1374	  };
1375	  return CreatePrimFuncPass(pass_func, 0, "tl.PipelinePlanning", {});
1376	}
1377	
1378	TVM_FFI_STATIC_INIT_BLOCK() {
1379	  namespace refl = reflection;
1380	  refl::GlobalDef().def("tl.transform.PipelinePlanning", PipelinePlanning);
1381	}
1382	
1383	} // namespace tl
1384	} // namespace tvm
